t.script:
(function () {
    var form = document.getElementById('wl_join_form');
    var size = document.getElementById('wl_party_size');
    /* 0 / missing = no limit for this restaurant (same rule as the server). */
    var max = parseInt(size.getAttribute('max'), 10) || 0;
    document.querySelectorAll('.wl-step-btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
            var v = (parseInt(size.value, 10) || 0) + parseInt(btn.dataset.step, 10);
            v = Math.max(v, 1);
            size.value = max ? Math.min(v, max) : v;
            check(size, checkSize);
        });
    });

    /* ---- Same rules as pos.waitlist.entry (_clean_guest_name / _clean_phone) ---- */
    var NAME_RE = /^\p{L}[\p{L}\p{M}]*( \p{L}[\p{L}\p{M}]*)*$/u;
    var PHONE_INVALID = 'Please enter a valid phone number for the selected country.';
    function checkName(input) {
        var v = input.value.trim().replace(/\s+/g, ' ');
        if (!v) { return 'Please enter your name.'; }
        if (!NAME_RE.test(v)) { return 'Please enter a name using letters and spaces only.'; }
        return '';
    }
    /* Any country: validated with libphonenumber (same rules as the server's
       "phonenumbers" library) for the country picked next to the field. */
    function checkPhone(input) {
        var v = input.value.trim();
        if (!v) { return 'Please enter your phone number.'; }
        if (!/^\+?[0-9\s().\-]+$/.test(v)) { return PHONE_INVALID; }
        var country = document.getElementById(input.id + '_country').value;
        var lib = window.libphonenumber;
        if (!lib || !lib.parsePhoneNumberFromString) {
            /* Library unavailable (offline / blocked): length only, the server checks fully. */
            var n = v.replace(/\D/g, '').length;
            return n >= 6 && n <= 15 ? '' : PHONE_INVALID;
        }
        var number = lib.parsePhoneNumberFromString(v, country);
        if (!number || !number.isValid()) { return PHONE_INVALID; }
        if (number.country === 'IN' && !/^[789][0-9]{9}$/.test(String(number.nationalNumber))) {
            return 'Please enter a valid 10-digit Indian mobile number starting with 7, 8 or 9.';
        }
        return '';
    }
    function checkSize(input) {
        var raw = String(input.value).trim();
        var n = /^[0-9]+$/.test(raw) ? parseInt(raw, 10) : 0;
        if (n < 1 || (max && n > max)) {
            return max ? 'Party size must be a whole number between 1 and ' + max
                         + '. For a larger group, please speak with the host.'
                       : 'Party size must be a whole number of at least 1.';
        }
        return '';
    }
    function check(input, rule) {
        var msg = rule(input);
        var box = document.getElementById(input.id + '_err');
        box.textContent = msg;
        box.hidden = !msg;
        input.classList.toggle('wl-input-invalid', !!msg);
        input.setAttribute('aria-invalid', msg ? 'true' : 'false');
        return !msg;
    }
    var nameInput = document.getElementById('wl_guest_name');
    var phoneInput = document.getElementById('wl_phone');
    var findPhone = document.getElementById('wl_find_phone');
    [[nameInput, checkName], [phoneInput, checkPhone], [size, checkSize], [findPhone, checkPhone]].forEach(function (pair) {
        /* Show a field's error once the guest leaves it, then live while they fix it. */
        pair[0].addEventListener('blur', function () { if (pair[0].value) { check(pair[0], pair[1]); } });
        pair[0].addEventListener('input', function () {
            if (pair[0].classList.contains('wl-input-invalid')) { check(pair[0], pair[1]); }
        });
    });
    /* Changing the country re-checks a number already typed. */
    [phoneInput, findPhone].forEach(function (input) {
        document.getElementById(input.id + '_country').addEventListener('change', function () {
            if (input.value) { check(input, checkPhone); }
        });
    });

    form.addEventListener('submit', function (ev) {
        var btn = document.getElementById('wl_submit');
        if (btn.disabled) { ev.preventDefault(); return; }
        var ok = [check(nameInput, checkName), check(phoneInput, checkPhone), check(size, checkSize)];
        if (ok.indexOf(false) !== -1) {
            ev.preventDefault();
            var bad = form.querySelector('.wl-input-invalid');
            if (bad) { bad.focus(); }
            return;
        }
        /* The server also recovers repeated submits; this only spares the round trip. */
        btn.disabled = true;
        btn.textContent = 'Joining…';
    });
    var findForm = document.getElementById('wl_find_form');
    findForm.addEventListener('submit', function (ev) {
        var btn = document.getElementById('wl_find_submit');
        if (btn.disabled) { ev.preventDefault(); return; }
        if (!check(findPhone, checkPhone)) { ev.preventDefault(); findPhone.focus(); return; }
        btn.disabled = true;
        btn.textContent = 'Searching…';
    });
    var find = document.getElementById('wl_find');
    if (find.open) { find.scrollIntoView({block: 'center'}); }
    window.addEventListener('pageshow', function (ev) {
        /* Back button after joining / leaving: the browser restored an old copy of
           this form (and its "Track My Waitlist" link). Ask the server again: it
           only offers a visit that is still active, and a submit creates a new one. */
        if (ev.persisted) { window.location.reload(); return; }
        var btn = document.getElementById('wl_submit');
        btn.disabled = false;
        btn.textContent = 'Join Waitlist';
        var fbtn = document.getElementById('wl_find_submit');
        fbtn.disabled = false;
        fbtn.textContent = 'Find My Place';
    });
})();

(function () {
    function $(id) { return document.getElementById(id); }
    var url = $('wl_status_poll') ? $('wl_status_poll').dataset.url : null;
    var card = $('wl_status_card');
    var state = card.dataset.state;
    var CLOSED = {cancelled: 1, left: 1, no_show: 1};
    /* Same cadence as the KDS order-status screens. */
    var POLL_MS = 3000, IDLE_MS = 15000, TIMEOUT_MS = 8000;
    var timer = null, inflight = false;

    /* ---- Sound (Web Audio, like the KDS) + vibration ---- */
    var audioCtx = null;
    function ctx() {
        if (!audioCtx) {
            var AC = window.AudioContext || window.webkitAudioContext;
            if (AC) { audioCtx = new AC(); }
        }
        if (audioCtx && audioCtx.state === 'suspended') { audioCtx.resume(); }
        return audioCtx;
    }
    function tone(c, freq, start, dur) {
        var o = c.createOscillator(), g = c.createGain();
        o.type = 'sine';
        o.frequency.value = freq;
        g.gain.setValueAtTime(0.0001, start);
        g.gain.exponentialRampToValueAtTime(0.6, start + 0.02);
        g.gain.exponentialRampToValueAtTime(0.0001, start + dur);
        o.connect(g);
        g.connect(c.destination);
        o.start(start);
        o.stop(start + dur + 0.05);
    }
    function chime(times) {
        var c = ctx();
        if (!c) { return; }
        var t = c.currentTime + 0.05;
        for (var i = 0; i < times; i++) {
            tone(c, 880, t, 0.3);
            tone(c, 1174.7, t + 0.2, 0.3);
            tone(c, 1568, t + 0.4, 0.5);
            t += 1.1;
        }
    }
    function vibrate(pattern) {
        try { if (navigator.vibrate) { navigator.vibrate(pattern); } } catch (e) { /* unsupported (iPhone) */ }
    }
    /* ---- On / Off preference, kept on this phone across refreshes and visits ----
       localStorage first, a plain cookie as fallback (private tabs, storage blocked).
       Default On: alerts behave as before until the guest switches them off. */
    var PREF = 'hudson_wl_alerts';
    function readPref() {
        var v = null;
        try { v = window.localStorage.getItem(PREF); } catch (e) { /* storage blocked */ }
        if (v !== 'on' && v !== 'off') {
            var m = document.cookie.match(/(?:^|;\s*)hudson_wl_alerts=(on|off)/);
            v = m ? m[1] : 'on';
        }
        return v !== 'off';
    }
    function savePref(on) {
        var v = on ? 'on' : 'off';
        try { window.localStorage.setItem(PREF, v); } catch (e) { /* storage blocked */ }
        document.cookie = PREF + '=' + v + '; path=/waitlist/; max-age=31536000; SameSite=Lax';
    }
    var alertsOn = readPref();
    function paintAlerts() {
        $('wl_alerts_btn').setAttribute('aria-checked', alertsOn ? 'true' : 'false');
        $('wl_alerts_state').textContent = alertsOn
            ? 'On: your phone will ring and vibrate when your table is ready.'
            : 'Off: tap to turn on.';
    }
    paintAlerts();
    $('wl_alerts_btn').addEventListener('click', function () {
        alertsOn = !alertsOn;
        savePref(alertsOn);
        paintAlerts();
        if (alertsOn) {
            ctx();
            chime(1);
            vibrate(120);
        }
    });
    /* Any tap also unlocks audio (needed again after every page load). */
    document.addEventListener('pointerdown', function () { if (alertsOn) { ctx(); } }, {once: true});

    function flash(title) {
        document.title = title;
        card.classList.remove('wl-flash');
        void card.offsetWidth;
        card.classList.add('wl-flash');
    }
    function alertSeated() {
        if (alertsOn) {
            vibrate([500, 200, 500, 200, 900]);
            chime(3);
        }
        flash('🔔 Your table is ready!');
    }
    /* Every other status change (Left, Cancelled, No Show, back to Waiting...). */
    function alertStatus(label) {
        if (alertsOn) {
            vibrate([300, 150, 300]);
            chime(1);
        }
        flash('🔔 ' + label);
    }

    /* ---- Live update: fill the page in place, never reload ---- */
    function render(s) {
        var prev = state;
        state = s.state;
        card.dataset.state = state;
        $('wl_state_label').textContent = s.state_label;
        $('wl_detail_state').textContent = s.state_label;
        $('wl_state_badge').className = 'wl-badge wl-state ' + (state === 'waiting' ? 'wl-badge-open'
            : (state === 'seated' ? 'wl-state-seated' : 'wl-state-done'));
        $('wl_state_dot').hidden = !s.active;
        $('wl_wait').textContent = s.estimated_wait_label || '';
        var atTable = state === 'seated' && !s.completed;
        $('wl_stats').hidden = state !== 'waiting';
        $('wl_seated_alert').hidden = !atTable;
        $('wl_seated_table').textContent = 'Please go to Table ' + (s.table || '') + '.';
        $('wl_seated_table').hidden = !s.table;
        $('wl_seated_host').hidden = !!s.table;
        $('wl_msg_seated').hidden = !atTable;
        $('wl_msg_completed').hidden = !s.completed;
        $('wl_detail_table').textContent = s.table || '';
        $('wl_detail_table_row').hidden = !s.table;
        $('wl_msg_closed').hidden = !CLOSED[state];
        if ($('wl_join_again')) { $('wl_join_again').hidden = !!s.active; }
        $('wl_alerts').hidden = !s.active;
        if (state !== prev) {
            if (state === 'seated') { alertSeated(); } else { alertStatus(s.state_label); }
        }
        if (!s.active) { endTracking(); }
    }
    function setLive(ok) {
        if (gone) { return; }
        $('wl_live').classList.toggle('wl-live-off', !ok);
        $('wl_live_text').textContent = ok ? 'Live updates' : 'Reconnecting…';
    }
    /* Only a waiting guest is tracked. As soon as the server reports the visit closed
       (Seated is the end of the journey, or Cancelled / Left / No Show) the page shows
       that final state and stops for good: the server answers 410 from then on. */
    var gone = !url;
    function endTracking() {
        gone = true;
        clearTimeout(timer);
        $('wl_live').classList.remove('wl-live-off');
        $('wl_live').classList.add('wl-live-ended');
        $('wl_live_text').textContent = 'Tracking ended for this visit';
    }
    function schedule() {
        clearTimeout(timer);
        if (gone) { return; }
        timer = setTimeout(poll, document.hidden ? IDLE_MS : POLL_MS);
    }
    function renderGone() {
        /* Entry removed from the back office: closed for good, stop polling. */
        endTracking();
        if (!CLOSED[state]) { alertStatus('Closed'); }
        state = 'cancelled';
        card.dataset.state = state;
        $('wl_state_label').textContent = 'Closed';
        $('wl_detail_state').textContent = 'Closed';
        $('wl_state_badge').className = 'wl-badge wl-state wl-state-done';
        $('wl_state_dot').hidden = true;
        $('wl_stats').hidden = true;
        $('wl_seated_alert').hidden = true;
        $('wl_msg_seated').hidden = true;
        $('wl_msg_completed').hidden = true;
        $('wl_detail_table_row').hidden = true;
        $('wl_msg_closed').hidden = false;
        if ($('wl_join_again')) { $('wl_join_again').hidden = false; }
        $('wl_alerts').hidden = true;
    }
    function poll() {
        if (inflight || gone) { return; }
        inflight = true;
        clearTimeout(timer);
        /* A request stuck in the tunnel is aborted, so the loop can never stall. */
        var ctrl = window.AbortController ? new AbortController() : null;
        var abortTimer = ctrl ? setTimeout(function () { ctrl.abort(); }, TIMEOUT_MS) : null;
        fetch(url + '?t=' + Date.now(), {cache: 'no-store', credentials: 'same-origin', signal: ctrl ? ctrl.signal : undefined})
            .then(function (r) {
                if (r.status === 404) { return {gone: true}; }
                /* 410: the visit is closed; the body is its final state (shown once). */
                if (!r.ok && r.status !== 410) { throw new Error(String(r.status)); }
                return r.json();
            })
            .then(function (s) { setLive(true); if (s.gone) { renderGone(); } else { render(s); } })
            .catch(function () { setLive(false); })
            .then(function () { clearTimeout(abortTimer); inflight = false; schedule(); });
    }
    /* Phones pause timers in the background: check at once when the guest comes back. */
    document.addEventListener('visibilitychange', function () { if (!document.hidden) { poll(); } });
    window.addEventListener('focus', poll);
    window.addEventListener('online', poll);
    window.addEventListener('pageshow', function (ev) { if (ev.persisted) { poll(); } });
    schedule();
})();
